function largestSelfCounting(arr: number[]): number {
  const n = arr.length;
  const count = new Array(n + 1).fill(0);
  for (const v of arr) if (v <= n) count[v]++;
  for (let v = n; v >= 1; v--) if (count[v] === v) return v;
  return -1;
}

