class Solution:
    def largestSelfCounting(self, arr: List[int]) -> int:
        n = len(arr)
        count = [0] * (n + 1)
        for v in arr:
            if v <= n:
                count[v] += 1
        for v in range(n, 0, -1):
            if count[v] == v:
                return v
        return -1

